import { readdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

/** Keep bundled production migrations explicit and ordered without manual imports. */
export async function generateMigrationRegistry(
    directory = new URL('../../migrations/', import.meta.url),
) {
    const files = (await readdir(directory))
        .filter((file) => /^Migration\d+\.ts$/.test(file))
        .toSorted();
    const names = files.map((file) => file.slice(0, -3));
    const output = [
        '// Generated by db:migrations:gen. Do not edit.',
        ...names.map((name) => `import { ${name} } from './${name}.ts';`),
        `export const migrations = [${names.join(', ')}] as const;`,
        '',
    ].join('\n');
    const target = new URL('registry.gen.ts', directory);
    const previous = await readFile(target, 'utf8').catch(() => '');
    if (previous !== output) {
        await writeFile(target, output);
    }
    return fileURLToPath(target);
}
if (import.meta.main) {
    await generateMigrationRegistry();
}
